#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/ztest.h>

static int device_test_init_fn(const struct device *dev);

/*
 * Used to test that the API can be extended by the subsystem.
 */
struct device_test_api_extends {
	void (*foo)(void);
	int (*bar)(int);
};

/*
 * Used to test that the common API can be used by the subsystem.
 */
struct device_test_api {
	struct device_test_api_extends *extended;
	void (*foo)(void);
};

/*
 * Grandchild API to test transitive relations
 */
struct device_test_api_grandchild {
	int field;
};

static void device_test_foo(void)
{
}

static int device_test_bar(int val)
{
	return val;
}

static struct device_test_api_extends extended_api = {
	.foo = device_test_foo,
	.bar = device_test_bar,
};

static struct device_test_api api = {
	.extended = &extended_api,
	.foo = device_test_foo,
};

static struct device_test_api_grandchild grandchild_api = {
	.field = 42,
};

/* For tracking initialization sequence */
#define MAX_INIT_SEQUENCE 10
static const struct device *init_sequence[MAX_INIT_SEQUENCE];
static int init_sequence_idx;

static int deinit_sequence[MAX_INIT_SEQUENCE];
static int deinit_sequence_idx;

static int device_test_init_fn(const struct device *dev)
{
	if (init_sequence_idx < MAX_INIT_SEQUENCE) {
		init_sequence[init_sequence_idx++] = dev;
	}

	return 0;
}

static int device_test_deinit_fn(const struct device *dev)
{
	if (deinit_sequence_idx < MAX_INIT_SEQUENCE) {
		deinit_sequence[deinit_sequence_idx++] = 1;
	}

	return 0;
}

DEVICE_DEFINE(device_test, "device_test", &device_test_init_fn,
		device_test_deinit_fn, NULL, NULL,
		POST_KERNEL, 10, &api);

DEVICE_DEFINE(device_test_no_api, "device_test_no_api", &device_test_init_fn,
		NULL, NULL, NULL,
		POST_KERNEL, 20, NULL);

DEVICE_DEFINE(device_test_api_rom, "device_test_api_rom",
		&device_test_init_fn, NULL, NULL, NULL,
		POST_KERNEL, 30, &api);

/* Create an "extended" device that uses the API from device_test_api_rom */
DEVICE_DEFINE(device_test_api_rom_extended, "device_test_api_rom_extended",
		&device_test_init_fn, NULL, NULL, NULL,
		POST_KERNEL, 40, &extended_api);

/* Create a "sibling" extended device that should not be found */
DEVICE_DEFINE(device_test_api_rom_extended_sibling,
		"device_test_api_rom_extended_sibling",
		&device_test_init_fn, NULL, NULL, NULL,
		POST_KERNEL, 40, &extended_api);

/* Create a "grandchild" device that should not be found */
DEVICE_DEFINE(device_test_api_rom_grandchild,
		"device_test_api_rom_grandchild",
		&device_test_init_fn, NULL, NULL, NULL,
		POST_KERNEL, 40, &grandchild_api);

/* Devices for testing init levels and priorities */
DEVICE_DEFINE(dev_pre_21, "", &device_test_init_fn, NULL, NULL, NULL,
	      PRE_KERNEL_1, 21, &api);
DEVICE_DEFINE(dev_pre_40, "", &device_test_init_fn, NULL, NULL, NULL,
	      PRE_KERNEL_1, 40, &api);
DEVICE_DEFINE(dev_pre_20, "", &device_test_init_fn, NULL, NULL, NULL,
	      PRE_KERNEL_1, 20, &api);

DEVICE_DEFINE(dev_pre_50, "", &device_test_init_fn, NULL, NULL, NULL,
	      PRE_KERNEL_2, 50, &api);

DEVICE_DEFINE(dev_post_61, "", &device_test_init_fn, NULL, NULL, NULL,
	      POST_KERNEL, 61, &api);
DEVICE_DEFINE(dev_post_60, "", &device_test_init_fn, NULL, NULL, NULL,
	      POST_KERNEL, 60, &api);

DEVICE_DEFINE(dev_app_81, "", &device_test_init_fn, NULL, NULL, NULL,
	      APPLICATION, 81, &api);
DEVICE_DEFINE(dev_app_80, "", &device_test_init_fn, NULL, NULL, NULL,
	      APPLICATION, 80, &api);

static void test_device_get_binding_success(void)
{
	const struct device *dev;

	dev = device_get_binding("device_test");
	zassert_true(dev != NULL, "device_get_binding() failed");
	zassert_true(dev == &device_test, "device_get_binding() returned wrong device");
}

static void test_device_get_binding_fail(void)
{
	const struct device *dev;

	dev = device_get_binding("device_test_non_existent");
	zassert_true(dev == NULL, "device_get_binding() did not return NULL");
}

static void test_device_ready_success(void)
{
	const struct device *dev;

	dev = device_get_binding("device_test");
	zassert_true(device_is_ready(dev), "device_is_ready() failed");
}

static void test_device_ready_fail(void)
{
	const struct device *dev;

	dev = device_get_binding("device_test_non_existent");
	zassert_false(device_is_ready(dev), "device_is_ready() did not return false");
}

static void test_device_init_level(void)
{
	/*
	 * This is run after boot, so we are just checking the sequence
	 * of initialization calls that has been recorded at boot time.
	 */
	bool sequence_correct = true;
	int i;
	const struct device *expected_sequence[] = {
		&dev_pre_20,
		&dev_pre_21,
		&dev_pre_40,
		&dev_pre_50,
		&dev_post_60,
		&dev_post_61,
		&dev_app_80,
		&dev_app_81,
	};

	if (init_sequence_idx != ARRAY_SIZE(expected_sequence)) {
		TC_PRINT("Incorrect number of initializations\n");
		sequence_correct = false;
		goto out;
	}

	for (i = 0; i < init_sequence_idx; i++) {
		if (init_sequence[i] != expected_sequence[i]) {
			TC_PRINT("Incorrect sequence at index %d\n", i);
			TC_PRINT("Expected %s, got %s\n",
				 expected_sequence[i]->name,
				 init_sequence[i]->name);
			sequence_correct = false;
			goto out;
		}
	}

out:
	zassert_true(sequence_correct, "device_test_device_init_level");
}

static void test_device_init_priority(void)
{
	/*
	 * This is run after boot, so we are just checking the sequence
	 * of initialization calls that has been recorded at boot time.
	 */
	bool sequence_correct = true;
	int i;
	const struct device *expected_sequence[] = {
		&dev_pre_20,
		&dev_pre_21,
		&dev_pre_40,
		&dev_pre_50,
		&dev_post_60,
		&dev_post_61,
		&dev_app_80,
		&dev_app_81,
	};

	if (init_sequence_idx != ARRAY_SIZE(expected_sequence)) {
		TC_PRINT("Incorrect number of initializations\n");
		sequence_correct = false;
		goto out;
	}

	for (i = 0; i < init_sequence_idx; i++) {
		if (init_sequence[i] != expected_sequence[i]) {
			TC_PRINT("Incorrect sequence at index %d\n", i);
			TC_PRINT("Expected %s, got %s\n",
				 expected_sequence[i]->name,
				 init_sequence[i]->name);
			sequence_correct = false;
			goto out;
		}
	}

out:
	zassert_true(sequence_correct, "device_test_device_init_priority");
}

static void test_device_api(void)
{
	const struct device *dev = device_get_binding("device_test_api_rom");
	const struct device_test_api *dev_api =
		(const struct device_test_api *)dev->api;

	zassert_true(dev_api == &api, "Invalid API pointer");
	zassert_true(dev_api->foo == device_test_foo, "Invalid function pointer");

	dev_api->foo();
}

static void test_device_api_extends(void)
{
	const struct device *dev =
		device_get_binding("device_test_api_rom_extended");
	const struct device_test_api_extends *dev_api =
		(const struct device_test_api_extends *)dev->api;

	zassert_true(dev_api == &extended_api, "Invalid API pointer");
	zassert_true(dev_api->foo == device_test_foo, "Invalid function pointer");
	zassert_true(dev_api->bar(10) == 10, "Invalid return value");
}

static void test_device_api_extends_sibling(void)
{
	const struct device *dev =
		device_get_binding("device_test_api_rom_extended_sibling");
	const struct device_test_api_extends *dev_api =
		(const struct device_test_api_extends *)dev->api;

	zassert_true(dev_api == &extended_api, "Invalid API pointer");
	zassert_true(dev_api->foo == device_test_foo, "Invalid function pointer");
	zassert_true(dev_api->bar(10) == 10, "Invalid return value");
}

static void test_device_api_extends_grandchild(void)
{
	const struct device *dev =
		device_get_binding("device_test_api_rom_grandchild");
	const struct device_test_api_grandchild *dev_api =
		(const struct device_test_api_grandchild *)dev->api;

	zassert_true(dev_api == &grandchild_api, "Invalid API pointer");
	zassert_true(dev_api->field == 42, "Invalid field value");
}

static void test_deinit_success_and_redeinit(void)
{
	const struct device *dev = DEVICE_GET(device_test);
	int err;

	/* Test that we can deinitialize a device */
	err = device_deinit(dev);
	zassert_ok(err, "failed to de-initialize device (err %d)", err);

	/* Test that we can re-initialize a device */
	err = device_init(dev);
	zassert_ok(err, "failed to re-initialize device (err %d)", err);
}

void test_main(void)
{
	ztest_test_suite(device,
			 ztest_unit_test(test_device_get_binding_success),
			 ztest_unit_test(test_device_get_binding_fail),
			 ztest_unit_test(test_device_ready_success),
			 ztest_unit_test(test_device_ready_fail),
			 ztest_unit_test(test_device_init_priority),
			 ztest_unit_test(test_device_init_level),
			 ztest_unit_test(test_device_api),
			 ztest_unit_test(test_device_api_extends),
			 ztest_unit_test(test_device_api_extends_sibling),
			 ztest_unit_test(test_device_api_extends_grandchild),
			 ztest_unit_test(test_deinit_success_and_redeinit)
			 );
	ztest_run_test_suite(device);
}
